WITH customer_purchases AS ( SELECT c.c_customer_id, cs.cs_sold_date_sk, cs.cs_order_number, cs.cs_net_profit, cs.cs_net_paid, p.p_promo_id FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk ), customer_agg AS ( SELECT c_customer_id, MIN(cs_sold_date_sk) AS first_purchase_date, MAX(cs_sold_date_sk) AS last_purchase_date, COUNT(DISTINCT cs_order_number) AS total_orders, SUM(cs_net_profit) AS total_profit, SUM(cs_net_paid) AS total_paid FROM customer_purchases GROUP BY c_customer_id ) SELECT c_customer_id, first_purchase_date, last_purchase_date, total_orders, total_profit, total_paid, (last_purchase_date - first_purchase_date) AS days_between, CASE WHEN (last_purchase_date - first_purchase_date) > 180 AND total_orders > 5 THEN 'Loyal' ELSE 'New' END AS customer_segment, RANK() OVER (ORDER BY total_profit DESC) AS profit_rank, DENSE_RANK() OVER (ORDER BY total_orders DESC) AS orders_rank FROM customer_agg WHERE total_orders >= 1 ORDER BY profit_rank LIMIT 100
